const GW=[['грунт','Грунтовые воды','Первый от поверхности водоносный слой над первым водоупорным пластом. Из них берут воду колодцы.'],['межпласт','Межпластовые воды','Вода между двумя водоупорными пластами, как в «слоёном пироге».'],['арт','Артезианский источник','Если пласты лежат чашей, межпластовая вода в середине под давлением: в скважине она бьёт фонтаном.'],['родник','Родник (ключ)','Место, где подземная вода сама выходит на поверхность — например, в овраге или на склоне долины.'],['прониц','Водопроницаемые породы','Пропускают воду: песок, галька, гравий.'],['упор','Водоупорные породы','Не пропускают воду: глина, гранит.']];
function figGround(hl){const H=k=>hl===k;let s='';const W=340;const top=x=>70+40*Math.sin(Math.PI*x/W);
 const curve=(f,x0,x1)=>{const a=[];for(let x=x0;x<=x1;x+=10)a.push([x,f(x)]);return a;};
 const surf=[[0,46],[120,40],[236,48],[250,84],[264,86],[278,50],[340,44]];
 const A1=x=>top(x),A1b=x=>top(x)+16,AQ=x=>top(x)+38;
 s+=PG([...surf,[340,A1(340)],...curve(A1,0,340).reverse()],{f:H('прониц')?'var(--hl)':'var(--warn)',fo:H('прониц')?0.6:0.22,s:'var(--fig)',sw:0.8});
 s+=PG([...curve(x=>A1(x)-10,0,340),...curve(A1,0,340).reverse()],{f:H('грунт')?'var(--bad)':WATER,fo:H('грунт')?0.7:0.5});
 s+=PG([...curve(A1,0,340),...curve(A1b,0,340).reverse()],{f:H('упор')?'var(--hl)':'var(--fig)',fo:H('упор')?0.75:0.4,s:'var(--fig)',sw:0.8});
 s+=PG([...curve(A1b,0,340),...curve(AQ,0,340).reverse()],{f:H('межпласт')||H('арт')?'var(--bad)':WATER,fo:H('межпласт')||H('арт')?0.6:0.5,s:'var(--fig)',sw:0.6});
 s+=PG([...curve(AQ,0,340),[340,200],[0,200]],{f:H('упор')?'var(--hl)':'var(--fig)',fo:H('упор')?0.75:0.4,s:'var(--fig)',sw:0.8});
 s+=RECT(166,10,8,A1b(170)+12-10,{f:'var(--card)',s:'var(--fig)',sw:1})+PATH('M170,12 Q156,-2 146,16 M170,12 Q184,-2 194,16',{s:H('арт')?'var(--bad)':WATER,sw:H('арт')?3.5:2.5});
 s+=RECT(62,30,10,A1(67)-36,{f:'var(--card)',s:'var(--fig)',sw:1})+TX(67,26,'колодец',{fs:10.5,halo:2});
 s+=CIR(257,86,H('родник')?7:4.5,{f:H('родник')?'var(--bad)':WATER,s:'var(--fig)',sw:1})+TX(262,104,'родник',{fs:10.5,a:'start',halo:2});
 s+=TX(180,26,'артезианская скважина',{fs:10.5,a:'start',halo:2})+TX(26,A1(26)-14,'грунтовые воды',{fs:10,a:'start',halo:2})+TX(26,A1b(26)-4,'водоупорный слой (глина)',{fs:9.5,a:'start',halo:2})+TX(26,AQ(26)-8,'межпластовые воды',{fs:10,a:'start',halo:2})+TX(26,AQ(26)+18,'водоупорный слой',{fs:9.5,a:'start',halo:2})+TX(300,60,'песок',{fs:10,halo:2});
 return SV(340,200,s,'Подземные воды',340);}
