const LAKE_PTS=[['Каспийское море',[50,42],'самое большое озеро, бессточное, солоноватое; между Европой и Азией'],['Байкал',[108,53.5],'самое глубокое озеро мира (1642 м), в Южной Сибири'],['Верхнее',[-88,47.5],'крупнейшее пресное озеро по площади, Северная Америка'],['Виктория',[33,-1],'крупнейшее озеро Африки, у экватора'],['Ладожское',[31.5,61],'самое большое озеро Европы, у Санкт-Петербурга'],['Танганьика',[30,-6.5],'второе по глубине озеро мира (1470 м), в Африке']];
