G(5,()=>CH('Как определить, к бассейну какого океана относится река?','По тому, куда в итоге попадает её вода (в какое море, а оно — в какой океан)',['По длине реки','По цвету воды','По направлению, откуда дует ветер'],{short:'Бассейн — куда в итоге стекает вода.',explain:'Река относится к бассейну того океана, куда <b>в конце концов</b> попадает её вода. Если вода не доходит до океана (Волга → Каспий) — это <b>бессточная</b> область.',explain2:'Проследи путь капли от реки до океана.'}),{rule:true});
G(9,()=>CH('★ Устье реки ниже уровня океана (например, −28 м). Как найти падение?','Высота истока + |высота устья| (минус на минус даёт плюс)',['Высота истока − 28','Только высота истока','Высота истока : 28'],{short:'Падение = исток − (−28) = исток + 28.',explain:'Падение = исток − устье. Если устье −28 м: ${M}. Падение <b>больше</b> высоты истока.'.replace('${M}',M('исток − (−28) = исток + 28')),explain2:'Река спускается до нуля и ещё на 28 м ниже.'}),{rule:true,star:true});
G(9,()=>{const v=pick([1,2,0.5]),d=pick([18,36,72]);const t=d*1000/v/3600;if(!Number.isInteger(t*10))return null;return NUM(t,{q:`★ Скорость течения реки — ${N(v)} м/с. За сколько часов вода проплывёт ${d} км?`,short:`${d} км = ${d*1000} м; ${d*1000} : ${N(v)} = ${N(d*1000/v)} с = ${N(t)} ч.`,explain:`${M(`${d*1000} : ${N(v)} = ${N(d*1000/v)} с`)}; в часе 3600 с: ${M(`${N(d*1000/v)} : 3600 = ${N(t)} ч`)}.`,explain2:`${N(v)} м/с = ${N(v*3.6)} км/ч. ${d} : ${N(v*3.6)} = ${N(t)} ч.`});},{star:true});
/* ---------------- widgets ---------------- */
function onTheory(root){
 const r=root.querySelector('#w-river');
 if(r){r.innerHTML=`<b>🏞 Река от истока до устья: нажимай на части</b>${BTNS(RPARTS.map((p,i)=>['rp'+i,p[1]]))}<div id="rP" class="fig"></div><div id="rT" style="text-align:center;line-height:1.6;min-height:3em"></div>`;
  let hl=null;const g=id=>r.querySelector('#'+id);const u=()=>{g('rP').innerHTML=figRiver({hl});const p=RPARTS.find(x=>x[0]===hl);g('rT').innerHTML=p?`<b>${p[1]}</b> — ${p[2]}`:'Синие стрелки — направление течения. Нажми на название части.';RPARTS.forEach((p,i)=>{g('rp'+i).className='btn'+(hl===p[0]?'':' ghost');});};
  RPARTS.forEach((p,i)=>{g('rp'+i).onclick=()=>{hl=p[0];u();};});u();}
 const q=root.querySelector('#w-reg');
 if(q){q.innerHTML=`<b>📈 Год из жизни реки: двигай месяц</b>${SL('qM','Месяц:',0,11,1,4)}<div id="qP" class="fig"></div><div id="qT" style="text-align:center;line-height:1.6;min-height:3em"></div>`;
  const g=id=>q.querySelector('#'+id);const u=()=>{const m=+g('qM').value;g('qMo').textContent=['январь','февраль','март','апрель','май','июнь','июль','август','сентябрь','октябрь','ноябрь','декабрь'][m];const ph=phaseOf(m);g('qP').innerHTML=figRegime(m);g('qT').innerHTML=`<span class="out">${cap(ph[0])}</span><br>${ph[1]}`;};
  g('qM').oninput=u;u();}
 const w=root.querySelector('#w-ground');
 if(w){w.innerHTML=`<b>💧 Подземные воды: нажимай</b>${BTNS(GW.map((p,i)=>['gw'+i,p[1]]))}<div id="gP" class="fig"></div><div id="gT" style="text-align:center;line-height:1.6;min-height:3em"></div>`;
  let hl=null;const g=id=>w.querySelector('#'+id);const u=()=>{g('gP').innerHTML=figGround(hl);const p=GW.find(x=>x[0]===hl);g('gT').innerHTML=p?`<b>${p[1]}</b> — ${p[2]}`:'Нажми на кнопку — слой подсветится.';GW.forEach((p,i)=>{g('gw'+i).className='btn'+(hl===p[0]?'':' ghost');});};
  GW.forEach((p,i)=>{g('gw'+i).onclick=()=>{hl=p[0];u();};});u();}
}

